<script setup lang="ts">
import { computed,ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { scanner } from '@/platform/scanner'
import { coldStorageApi } from '../../api/cold-storage.api'
import ColdImagePicker from '../../components/ColdImagePicker.vue'
import type { BareScanResult } from '../../models/cold-storage'
const date=ref(''),code=ref(''),scanInfo=ref<BareScanResult>(),bunchNum=ref(''),images=ref<string[]>([]),remark=ref(''),scanning=ref(false),submitting=ref(false)
const canSubmit=computed(()=>!!scanInfo.value&&Number.isInteger(Number(bunchNum.value))&&Number(bunchNum.value)>0&&images.value.length>0)
async function scan(){if(scanning.value)return;scanning.value=true;try{const result=await scanner.scan();code.value=result.value;scanInfo.value=await coldStorageApi.scanBare(result.value)}catch(e){if(e instanceof Error&&!/cancel/i.test(e.message))uni.showToast({title:e.message||'扫码识别失败',icon:'none'})}finally{scanning.value=false}}
function reset(){code.value='';scanInfo.value=undefined;bunchNum.value='';images.value=[];remark.value=''}
async function submit(){if(!canSubmit.value)return uni.showToast({title:'请完成扫码、数量和照片',icon:'none'});submitting.value=true;try{await coldStorageApi.registerBare({content:code.value,bunchNum:Number(bunchNum.value),imageUrls:images.value,remark:remark.value});uni.showToast({title:'暂存登记成功',icon:'success'});setTimeout(()=>uni.navigateBack(),600)}catch(e){uni.showToast({title:e instanceof Error?e.message:'登记失败',icon:'none'})}finally{submitting.value=false}}
onLoad(query=>date.value=String(query?.date||''))
</script>
<template><view class="page"><view class="section"><view class="title"><strong>扫描花材二维码</strong><text>{{scanInfo?'已识别':'待扫码'}}</text></view><view class="scan-result"><text>{{code||'扫描后自动识别客户、场次和货位'}}</text><button @click="scan">{{scanning?'识别中…':scanInfo?'重新扫描':'开始扫码'}}</button></view></view>
<view class="section"><view class="title"><strong>识别结果</strong></view><view v-if="scanInfo" class="result"><view class="customer"><strong>{{scanInfo.purchaserNick||'未命名客户'}}</strong><text>{{scanInfo.purchaserMobile}}</text></view><view><text>暂存场次</text><strong>{{scanInfo.roundNo||date||'—'}}</strong></view><view><text>货位号</text><strong>{{scanInfo.locationNo||'—'}}</strong></view><view><text>收货地址</text><strong>{{scanInfo.receiveAddress||'—'}}</strong></view><view><text>原发货单</text><strong>{{scanInfo.originSendNo||'—'}}</strong></view></view><view v-else class="empty">请先扫描花材二维码</view></view>
<view class="section"><view class="title"><strong>确认登记信息</strong></view><view class="number"><text>暂存数量 <i>必填</i></text><view><input v-model="bunchNum" type="number" placeholder="请输入"/><strong>扎</strong></view></view></view>
<view class="section"><view class="title"><strong>入库照片</strong><text>必填</text></view><ColdImagePicker v-model="images"/><textarea v-model="remark" maxlength="500" placeholder="特殊备注（选填），可记录品种、等级等信息"/></view>
<view class="footer"><button class="cancel" @click="reset">清空</button><button :disabled="!canSubmit||submitting" @click="submit">{{submitting?'提交中…':'确认提交'}}</button></view></view></template>
<style scoped lang="scss">
.page{min-height:100vh;padding:24rpx 24rpx 150rpx}.section{margin-bottom:16rpx;padding:24rpx;border-radius:22rpx;background:#fff;box-shadow:var(--wms-shadow-card)}.title{display:flex;align-items:center;justify-content:space-between;margin-bottom:20rpx}.title strong{font-size:24rpx}.title text{color:var(--wms-primary-700);font-size:18rpx}.scan-result{display:flex;align-items:center;gap:14rpx}.scan-result>text{min-width:0;flex:1;overflow:hidden;color:var(--wms-text-secondary);font-size:20rpx;white-space:nowrap;text-overflow:ellipsis}.scan-result button{height:64rpx;margin:0;padding:0 20rpx;border:0;border-radius:13rpx;background:var(--wms-primary-700);color:#fff;font-size:20rpx;line-height:64rpx}.result{display:grid;grid-template-columns:1fr 1fr;gap:20rpx}.result view text,.result view strong{display:block}.result view text{color:var(--wms-text-secondary);font-size:18rpx}.result view strong{margin-top:6rpx;font-size:21rpx;word-break:break-all}.result .customer{grid-column:1/3;padding:17rpx;border-radius:13rpx;background:var(--wms-surface-soft)}.result .customer strong{margin:0;color:var(--wms-primary-700);font-size:25rpx}.result .customer text{margin-top:5rpx}.empty{padding:50rpx 20rpx;border:2rpx dashed var(--wms-border);border-radius:14rpx;color:var(--wms-text-secondary);font-size:20rpx;text-align:center}.number{display:flex;align-items:center;justify-content:space-between}.number>text{font-size:21rpx}.number i{color:var(--wms-danger);font-size:17rpx;font-style:normal}.number>view{display:flex;width:260rpx;height:68rpx;align-items:center;padding:0 16rpx;border-radius:13rpx;background:var(--wms-page)}.number input{min-width:0;flex:1;font-size:22rpx}.number strong{font-size:20rpx}.section textarea{box-sizing:border-box;width:100%;height:130rpx;margin-top:22rpx;padding:17rpx;border-radius:13rpx;background:var(--wms-page);font-size:20rpx}.footer{position:fixed;right:0;bottom:0;left:0;display:flex;gap:16rpx;padding:16rpx 24rpx calc(18rpx + env(safe-area-inset-bottom));background:#fff}.footer button{height:78rpx;flex:1;border:0;border-radius:15rpx;background:var(--wms-primary-700);color:#fff;font-size:23rpx;line-height:78rpx}.footer .cancel{background:var(--wms-surface-soft);color:var(--wms-primary-700)}.footer button[disabled]{background:#bdccc9}
</style>
